#include <iostream>
#include <random>
#include <vector>

int main() {
    // Define weights for outcomes
    std::vector<double> weights = {1.0, 2.0, 3.0};
    // Create a discrete_distribution with specified weights
    std::discrete_distribution<int> dist(weights.begin(), weights.end());
    // Initialize random number generator
    std::mt19937 gen(std::random_device{}());
    // Generate and output 10 random outcomes according to the distribution
    for (int i = 0; i < 10; ++i) {
        int outcome = dist(gen);
        std::cout << "Outcome: " << outcome << std::endl;
    }
    return 0;
}
